-- 014_n2_words_kasuga
-- N2 單字匯入：kasuga（共 906 字）
-- 資料源：stephenmk/yomitan-jlpt-vocab (CC-BY, Jonathan Waller / Tanos)
-- 中文翻譯：Claude（學生友善口語風格）

with new_words as (
  returning id, lemma
)
select
  (select id from shrines where slug = 'kasuga'),
  nw.id,
  row_number() over (order by nw.lemma)
from new_words nw;
